'use client';

import React, { useEffect, useState, use } from 'react';
import Link from 'next/link';
import { useDb } from '../../../../components/provider/db-provider';

export default function ArticlePage({ params }: { params: Promise<{ slug: string }> }) {
  const resolvedParams = use(params);
  const { db } = useDb();
  const [scrollProgress, setScrollProgress] = useState(0);

  const article = db.articles.find(a => a.id === resolvedParams.slug) || db.articles[0]; // fallback to first for prototype
  const author = db.users.find(u => u.id === article?.authorId);

  useEffect(() => {
    const handleScroll = () => {
      const scrollTop = document.documentElement.scrollTop || document.body.scrollTop;
      const scrollHeight = document.documentElement.scrollHeight - document.documentElement.clientHeight;
      const progress = scrollHeight > 0 ? scrollTop / scrollHeight : 0;
      setScrollProgress(progress);
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  if (!article) {
    return <div className="p-stack-lg text-center mt-24">Article not found</div>;
  }

  return (
    <>
      {/* Reading Progress Bar */}
      <div className="fixed top-16 left-0 w-full h-1 bg-surface-container-highest z-40">
        <div 
          className="h-full bg-primary-container w-full" 
          style={{ transformOrigin: '0% 50%', transform: `scaleX(${scrollProgress})`, transition: 'transform 0.1s linear' }}
        />
      </div>

      <div className="w-full max-w-container-max mx-auto px-margin-mobile md:px-gutter pb-stack-lg">
        {/* Article Header */}
        <article className="pt-stack-lg md:pt-24 max-w-[720px] mx-auto">
          <header className="mb-stack-md text-center flex flex-col items-center">
            <div className="flex items-center gap-2 mb-6">
              <span className="font-label-sm text-label-sm uppercase tracking-widest text-primary-container">Article</span>
              <span className="w-1 h-1 rounded-full bg-outline-variant"></span>
              <span className="font-label-sm text-label-sm uppercase tracking-widest text-secondary">{article.tags[0] || 'Christian Living'}</span>
            </div>

            <h1 className="font-display-lg text-headline-lg-mobile md:text-display-lg text-primary mb-6 text-balance">
              {article.title}
            </h1>

            <p className="font-body-lg text-body-lg text-on-surface-variant mb-8 text-balance max-w-2xl italic">
              {article.excerpt}
            </p>

            <div className="flex items-center gap-4 text-on-surface-variant border-y border-outline-variant py-4 w-full justify-between">
              <div className="flex items-center gap-3">
                <img 
                  className="w-10 h-10 rounded-full object-cover border border-outline-variant" 
                  src={author?.avatarUrl || "https://lh3.googleusercontent.com/aida-public/AB6AXuDgUVrn5s8RpllfDjgO6IEDOiQNXWzTEXevCQTgW4Tzay_k_lcAcIzVWTkORiGaQU01j-nrphUR6gajsa4kc5whCRocS3A6oOyEJG0bssQkIP32oPsXYDAB3DUD0CuRU3BmT8tQ7H11DLPV5X7Jlq6YaJq0t9z0hrQxCf4Ci9GrM9FifGA_Q7HzDR3HYFG1M5NhQm0jNY2KXngP56mFTADmT3T1OXXFYLoVQIK1hM5ewJfw2xE7bDVO"}
                  alt="Author"
                />
                <div className="flex flex-col items-start">
                  <span className="font-label-sm text-label-sm text-on-surface">{author?.name || 'Unknown'}</span>
                  <span className="font-label-sm text-label-sm text-secondary opacity-70">
                    {new Date(article.publishedAt || article.createdAt).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' })}
                  </span>
                </div>
              </div>
              <div className="flex items-center gap-4">
                <span className="font-label-sm text-label-sm text-secondary opacity-70 hidden sm:inline-flex items-center gap-1">
                  <span className="material-symbols-outlined text-[16px]">schedule</span>
                  {article.readTime} min read
                </span>
                <div className="flex items-center gap-2">
                  <button aria-label="Bookmark" className="p-2 text-secondary hover:text-primary transition-colors rounded-full hover:bg-surface-container-low">
                    <span className="material-symbols-outlined">bookmark</span>
                  </button>
                  <button aria-label="Share" className="p-2 text-secondary hover:text-primary transition-colors rounded-full hover:bg-surface-container-low">
                    <span className="material-symbols-outlined">share</span>
                  </button>
                </div>
              </div>
            </div>
          </header>

          {/* Hero Image */}
          <figure className="mb-stack-lg rounded-[4px] overflow-hidden bg-surface-container-low border border-outline-variant/50 relative">
            <img 
              className="w-full aspect-[16/9] md:aspect-[21/9] object-cover" 
              src={article.coverImage || "https://lh3.googleusercontent.com/aida-public/AB6AXuAiRd8q9cA9X_4Absniwkn1rGdLxIyvIK_y2Jq92ioGxIn0btg7MkRTH9SWxLpI1vS1kRffWKMuwomghLqFLQOHVkgkks-FWlnnDasjX8cycrn0YUY1mqc4JWn1iyhfeVN2QDoTkwR4q49abMc6TPR-AuOUtfuZbRkwNq4OFg6VIiJh3nTGEl4mCu6SPxEPipvfhUYNH_IRa6okp-D22GNK5L96PvN--j92Agp-JoXImFkFvegFXKWf"}
              alt={article.title}
            />
            <figcaption className="p-3 text-left font-body-md text-[14px] italic text-secondary bg-surface-container-low/80 backdrop-blur-sm border-t border-outline-variant/30">
              Finding stillness in the early hours.
            </figcaption>
          </figure>

          {/* Article Body */}
          <div 
            className="font-body-lg text-body-lg text-on-surface space-y-6 leading-relaxed"
            dangerouslySetInnerHTML={{ __html: article.content }}
          />

          {/* Flourish Divider */}
          <div className="flex items-center justify-center my-stack-lg gap-4 opacity-50">
            <div className="h-[1px] w-16 bg-gradient-to-r from-transparent to-outline"></div>
            <span className="material-symbols-outlined text-outline text-[16px]">eco</span>
            <div className="h-[1px] w-16 bg-gradient-to-l from-transparent to-outline"></div>
          </div>

          {/* Author Bio */}
          <div className="bg-surface-container-low p-6 md:p-8 rounded-lg border border-outline-variant flex flex-col sm:flex-row gap-6 items-start sm:items-center">
            <img 
              className="w-20 h-20 rounded-full object-cover border border-outline-variant shrink-0" 
              src={author?.avatarUrl || "https://lh3.googleusercontent.com/aida-public/AB6AXuATQpKoBYxjP4debLywiJKTL5Pg8jjJTAoTs7N9GnNItsKl7R3-kmElmmW2Y_QFC5jRTNUHINw4jURsLzUVvh1RgN-sM2ZRxa393o4ZcE8TmudqPU7C1WdWDsOBIRIJzG_rYhT3f0WNOPg-62cOHPK7-bKPtHWNYyQGaRAUodsa71peAt6g7i0GOdGMP7Ousw4o2Mf0yR_6s-5m5Zk070olRvHV4YVWf_2JvUo1yKIfg-cQJydzVTYx"}
              alt={author?.name}
            />
            <div>
              <h3 className="font-headline-md text-[22px] text-primary mb-2">{author?.name || 'Unknown'}</h3>
              <p className="font-body-md text-on-surface-variant text-[15px] leading-snug">
                {author?.name} is a writer and theologian exploring the intersection of modern life and ancient faith.
              </p>
              <Link href="#" className="mt-3 font-label-sm text-label-sm text-primary-container uppercase tracking-widest hover:underline flex items-center gap-1">
                Read more by {author?.name?.split(' ')[0]} <span className="material-symbols-outlined text-[14px]">arrow_forward</span>
              </Link>
            </div>
          </div>
        </article>

        {/* Related Content (Bento style) */}
        <section className="mt-stack-lg pt-stack-md border-t border-outline-variant">
          <h2 className="font-display-lg text-headline-lg-mobile md:text-[40px] text-primary mb-8 text-center">More from {article.tags[0]}</h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {db.articles.filter(a => a.id !== article.id && a.status === 'PUBLISHED').slice(0, 3).map((relatedArticle, idx) => (
              <Link 
                key={relatedArticle.id}
                href={`/article/${relatedArticle.id}`} 
                className={`${idx === 0 ? 'md:col-span-2' : ''} group bg-surface-container-lowest rounded-lg border border-outline-variant overflow-hidden hover:border-outline transition-colors hover:shadow-sm`}
              >
                <div className={`flex ${idx === 0 ? 'flex-col md:flex-row h-full' : 'flex-col'}`}>
                  <div className={`w-full ${idx === 0 ? 'md:w-1/2 aspect-[4/3] md:aspect-auto md:h-full' : 'aspect-[4/3]'} relative overflow-hidden bg-surface-container-low`}>
                    <img 
                      className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700" 
                      src={relatedArticle.coverImage || "https://lh3.googleusercontent.com/aida-public/AB6AXuCVmVdlZR0hxE9NL-hYF-xdIchHL2sLHB1sxXvbnK0xEz0wS8h2MKXIuTiQaVL2lkYOWcKigYsgoTzM-SZ7GcvRa_KQQ59ljM0ogYSUXwtW4Q5jaBxNdZ8PCa6yzDVOlg4iQAZapB4f9jL0sRVik4o3N6QC8IrFDT7LlR2X-MOZHTU8Cxo5Z4_zm10oB1fi25TQhKq6mV06FMPYvIsy3_2UH4MbFcpYg9_LyXDIWpAfx8hhM_n_QLNv"}
                      alt={relatedArticle.title}
                    />
                  </div>
                  <div className={`${idx === 0 ? 'p-6 md:p-8 flex flex-col justify-center w-full md:w-1/2' : 'p-5 flex flex-col flex-grow'}`}>
                    <span className="font-label-sm text-label-sm uppercase tracking-widest text-secondary mb-3">{relatedArticle.tags[0]}</span>
                    <h3 className="font-headline-md text-headline-md text-primary mb-3 group-hover:text-primary-container transition-colors">
                      {relatedArticle.title}
                    </h3>
                    <p className={`font-body-md text-on-surface-variant ${idx === 0 ? 'line-clamp-3 mb-4' : 'line-clamp-2 text-[15px] mb-4'}`}>
                      {relatedArticle.excerpt}
                    </p>
                    <span className="font-label-sm text-label-sm text-secondary opacity-70 mt-auto pt-2">
                      {db.users.find(u => u.id === relatedArticle.authorId)?.name} · {new Date(relatedArticle.publishedAt || relatedArticle.createdAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
                    </span>
                  </div>
                </div>
              </Link>
            ))}
          </div>
        </section>
      </div>
    </>
  );
}

'use client';

import React, { use } from 'react';
import Link from 'next/link';
import { useDb } from '../../../../components/provider/db-provider';

export default function DevotionalPage({ params }: { params: Promise<{ slug: string }> }) {
  const resolvedParams = use(params);
  const { db } = useDb();

  // For the prototype, we can use an article but treat it as a devotional
  const article = db.articles.find(a => a.id === resolvedParams.slug) || db.articles[0];
  const author = db.users.find(u => u.id === article?.authorId);

  if (!article) {
    return <div className="p-stack-lg text-center mt-24">Devotional not found</div>;
  }

  return (
    <main className="max-w-[800px] mx-auto px-margin-mobile md:px-0 py-stack-lg flex flex-col space-y-stack-lg mt-8 min-h-[calc(100vh-200px)]">
      {/* Header Section */}
      <section className="text-center space-y-stack-sm pt-8">
        <p className="font-label-sm text-label-sm text-on-surface-variant uppercase tracking-widest">
          Daily Devotional · {new Date(article.publishedAt || article.createdAt).toLocaleDateString('en-US', { month: 'long', day: 'numeric' })}
        </p>
        <h1 className="font-headline-lg-mobile text-headline-lg-mobile md:font-headline-lg md:text-headline-lg text-on-surface">
          {article.title}
        </h1>
        <p className="font-body-md text-body-md text-secondary italic">
          {article.excerpt}
        </p>
      </section>

      {/* Primary Scripture Callout */}
      <section className="bg-surface-container-low border border-outline p-stack-md rounded-lg text-center relative shadow-sm">
        <div className="absolute -top-3 left-1/2 transform -translate-x-1/2 bg-surface-container-low px-4 border border-outline rounded-full flex items-center justify-center">
          <span className="material-symbols-outlined text-primary text-sm py-1">auto_stories</span>
        </div>
        <h2 className="font-label-lg text-label-lg text-primary mb-4">Scripture Passage</h2>
        <blockquote className="font-body-lg text-body-lg text-on-surface max-w-2xl mx-auto italic">
          "Whoever can be trusted with very little can also be trusted with much, and whoever is dishonest with very little will also be dishonest with much."
        </blockquote>
      </section>

      {/* Devotional Content */}
      <article 
        className="font-body-md text-body-md text-on-surface space-y-6 leading-relaxed"
        dangerouslySetInnerHTML={{ __html: article.content }}
      />

      {/* Action Bar */}
      <section className="flex flex-col sm:flex-row items-center justify-center gap-4 py-8 border-t border-b border-outline-variant">
        <button className="flex items-center gap-2 px-6 py-3 border border-outline rounded-full hover:bg-surface-container-low transition-colors w-full sm:w-auto justify-center group">
          <span className="material-symbols-outlined text-on-surface-variant group-hover:text-primary transition-colors">bookmark</span>
          <span className="font-label-lg text-label-lg text-on-surface">Bookmark</span>
        </button>
        <button className="flex items-center gap-2 px-6 py-3 bg-primary text-on-primary rounded-full hover:bg-primary-container transition-colors w-full sm:w-auto justify-center group shadow-sm">
          <span className="material-symbols-outlined text-on-primary group-hover:scale-110 transition-transform">check_circle</span>
          <span className="font-label-lg text-label-lg text-on-primary">Mark as Read</span>
        </button>
      </section>

      {/* Author Bio */}
      <section className="flex flex-col md:flex-row items-center md:items-start gap-6 bg-surface-container-lowest p-stack-sm rounded-lg border border-outline-variant">
        <div className="w-20 h-20 rounded-full overflow-hidden shrink-0 border border-outline">
          <img 
            className="w-full h-full object-cover" 
            src={author?.avatarUrl || "https://lh3.googleusercontent.com/aida-public/AB6AXuDyMpccX-VVUH-eywZ6gwcF8mgRWYlAh5wP4LETVSYjxIKKxTEBgS8BTujn-GRLV-0PZ4lM03USf6e72JiziV8a_OSTXvePXsdwALMTz4jghOhh9vDsUjZz22BtDWvM0-bIQ4O1rkSqGygtXs_xsZruItgD0YFd1rvfkGPtnL5EWjLhi0cl3-eMADwdMUI-V6HxTCheIRNkTN6yAjZKgyo6_npjq5rjoHHM9V2khHgAvS1vkGaVh8nu"}
            alt={author?.name}
          />
        </div>
        <div className="text-center md:text-left space-y-2">
          <h3 className="font-label-lg text-label-lg text-on-surface">{author?.name || 'Unknown Author'}</h3>
          <p className="font-label-sm text-label-sm text-secondary">Director of Theological Stewardship</p>
          <p className="font-body-md text-body-md text-on-surface-variant text-sm">
            {author?.name} has spent over two decades writing on the intersection of faith, daily work, and financial stewardship.
          </p>
        </div>
      </section>
    </main>
  );
}

'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { useDb } from '../../../components/provider/db-provider';

export default function LibraryPage() {
  const { db } = useDb();
  const [filter, setFilter] = useState('All Content');
  const [search, setSearch] = useState('');

  const publishedContent = db.articles.filter(a => a.status === 'PUBLISHED');

  const filteredContent = publishedContent.filter(article => {
    // Basic text search
    if (search && !article.title.toLowerCase().includes(search.toLowerCase())) return false;

    // Type filter (using tags as a proxy for type in this prototype)
    if (filter === 'All Content') return true;
    if (filter === 'Articles' && article.tags[0] === 'Christian Living') return true;
    if (filter === 'Sermons' && article.tags[0] === 'Theology') return true; // Just mapping for demo
    if (filter === 'Devotionals' && article.tags[0] === 'Church History') return true; // Just mapping for demo

    return false;
  });

  return (
    <div className="flex-1 min-h-[calc(100vh-200px)] flex flex-col relative w-full">
      {/* Header Section */}
      <div className="px-margin-mobile md:px-gutter py-stack-md border-b border-outline-variant bg-surface-bright mt-8">
        <div className="max-w-container-max mx-auto flex flex-col md:flex-row md:items-end justify-between gap-6">
          <div>
            <h1 className="font-display-lg text-headline-lg-mobile md:text-display-lg text-primary mb-2">Library</h1>
            <p className="font-body-md text-body-md text-secondary max-w-xl">Master archive of all published works, sermons, and devotionals.</p>
          </div>
          <div className="flex items-center gap-4 bg-surface-container-low p-2 rounded-lg border border-outline-variant">
            <span className="material-symbols-outlined text-secondary ml-2">search</span>
            <input 
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="bg-transparent border-none focus:ring-0 font-body-md text-body-md text-on-background placeholder:text-secondary/70 w-full md:w-64 outline-none" 
              placeholder="Search titles, authors, tags..." 
              type="text"
            />
          </div>
        </div>
      </div>

      {/* Filter & View Controls */}
      <div className="px-margin-mobile md:px-gutter py-4 border-b border-outline-variant bg-surface sticky top-[64px] z-30">
        <div className="max-w-container-max mx-auto flex flex-col md:flex-row justify-between items-center gap-4">
          <div className="flex gap-2 overflow-x-auto w-full md:w-auto pb-2 md:pb-0">
            {['All Content', 'Articles', 'Sermons', 'Devotionals'].map(f => (
              <button 
                key={f}
                onClick={() => setFilter(f)}
                className={`px-4 py-1.5 rounded-full font-label-sm text-label-sm whitespace-nowrap transition-colors ${filter === f ? 'bg-primary-container text-on-primary-container' : 'border border-outline-variant text-secondary hover:border-primary hover:text-primary'}`}
              >
                {f}
              </button>
            ))}
          </div>
          <div className="flex items-center gap-3 self-end md:self-auto">
            <button className="flex items-center gap-1 text-secondary hover:text-primary font-label-sm text-label-sm transition-colors">
              <span className="material-symbols-outlined text-sm">filter_list</span> Filter
            </button>
            <div className="w-px h-4 bg-outline-variant"></div>
            <button className="flex items-center gap-1 text-secondary hover:text-primary font-label-sm text-label-sm transition-colors">
              <span className="material-symbols-outlined text-sm">sort</span> Sort: Newest
            </button>
          </div>
        </div>
      </div>

      {/* Library Content Canvas */}
      <div className="flex-1 px-margin-mobile md:px-gutter py-stack-md bg-background">
        <div className="max-w-container-max mx-auto flex flex-col gap-6">
          {filteredContent.map(article => (
            <Link key={article.id} href={`/article/${article.id}`} className="block">
              <article className="group flex flex-col md:flex-row gap-6 p-4 md:p-6 bg-surface-container-low border border-outline-variant rounded-lg hover:border-outline transition-colors relative">
                <div className="w-full md:w-48 h-48 md:h-auto shrink-0 bg-surface-variant rounded flex items-center justify-center overflow-hidden">
                  <img 
                    className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" 
                    src={article.coverImage || "https://lh3.googleusercontent.com/aida-public/AB6AXuB7Nt8CdGZL46VLGraW9TAaoRlL-GM6OyMbsaKqiJ-KbmyJT92ctzzeMeGdsyW4lUxoKz600d5GvOSoJvMwnl6Dly6Fbml3UWIGbX6Ui0foJ87y5DXyw1-2PelEiwoIzdHpzhhc9W4wSPnPPCrxJ5aNz5x8fmT-WTHK7Y8EN4xn1jQ5rBbkBgl9ktLeQdPzzAWauBilMnOywyz1zkltvXzKPDkIUScSwod5XikxYyRztOzpaHpSOteh"}
                    alt={article.title}
                  />
                </div>
                <div className="flex-1 flex flex-col">
                  <div className="flex items-center gap-2 mb-2">
                    <span className="font-label-sm text-label-sm text-primary uppercase tracking-wider">{article.tags[0] || 'Article'}</span>
                    <span className="text-secondary">·</span>
                    <span className="font-label-sm text-label-sm text-secondary">
                      Published {new Date(article.publishedAt || article.createdAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}
                    </span>
                  </div>
                  <h2 className="font-headline-md text-headline-md text-on-background mb-3 group-hover:text-primary transition-colors">
                    {article.title}
                  </h2>
                  <p className="font-body-md text-body-md text-on-surface-variant mb-4 line-clamp-2">
                    {article.excerpt}
                  </p>
                  <div className="flex items-center gap-4 mt-auto pt-4 border-t border-outline-variant/50">
                    <div className="flex items-center gap-1 text-secondary">
                      <span className="material-symbols-outlined text-sm">visibility</span>
                      <span className="font-label-sm text-label-sm">{(Math.random() * 10).toFixed(1)}k</span>
                    </div>
                    <div className="flex items-center gap-1 text-secondary">
                      <span className="material-symbols-outlined text-sm">bookmark</span>
                      <span className="font-label-sm text-label-sm">{Math.floor(Math.random() * 500)}</span>
                    </div>
                    <div className="ml-auto flex gap-2">
                      <span className="p-2 text-secondary group-hover:text-primary rounded-full group-hover:bg-surface-container-high transition-colors flex items-center gap-1 font-label-sm text-label-sm">
                        Read <span className="material-symbols-outlined text-sm">arrow_forward</span>
                      </span>
                    </div>
                  </div>
                </div>
              </article>
            </Link>
          ))}

          {filteredContent.length === 0 && (
            <div className="py-12 text-center text-on-surface-variant font-body-md">
              No content found matching your filters.
            </div>
          )}
        </div>

        {filteredContent.length > 0 && (
          <div className="flex justify-center mt-stack-md">
            <button className="px-6 py-2 border border-outline-variant rounded text-primary font-label-sm text-label-sm hover:bg-surface-container-low transition-colors">
              Load More Archive
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { useDb } from '../../../components/provider/db-provider';

export default function SearchPage() {
  const { db } = useDb();
  const [query, setQuery] = useState('');
  const [filter, setFilter] = useState('All');

  const handleSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
    setQuery(e.target.value);
  };

  const results = db.articles.filter(article => {
    if (!query) return false;
    const q = query.toLowerCase();
    return article.title.toLowerCase().includes(q) || article.excerpt.toLowerCase().includes(q);
  });

  return (
    <div className="w-full max-w-container-max px-margin-mobile md:px-gutter mx-auto flex-grow flex flex-col gap-stack-lg py-stack-lg min-h-[calc(100vh-200px)]">

      {!query ? (
        <>
          <header className="w-full flex flex-col gap-stack-sm items-center text-center mt-12">
            <h1 className="font-headline-lg-mobile text-headline-lg-mobile md:font-headline-lg md:text-headline-lg text-primary">Search GreatGod</h1>
